INSERT INTO label_code (
    "ModuleName", "TemplateKey", "LabelCode", "Description", "_created", "_modified"
)
SELECT module_name, template_key, label_code, description, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM tmp_template_label
ON CONFLICT ("ModuleName", "TemplateKey", "LabelCode")
WHERE "ModuleName" IS NOT NULL AND "TemplateKey" IS NOT NULL AND "LabelCode" IS NOT NULL
DO UPDATE SET
    "Description" = EXCLUDED."Description",
    "_modified" = CURRENT_TIMESTAMP;

-- exact repeated phrase 공통화 이전 중복 seed 정리
-- 생성기 설명 지문이 있고 현재 common/common 정본에는 포함되지만 현재 GUI 정본에는 없는 행만 대상으로 한다.
-- 수동 등록 또는 향후 GUI override는 생성기 지문/현재 정본 조건을 모두 만족하지 않으므로 보존한다.
CREATE TEMP TABLE tmp_superseded_generated_page_label
ON COMMIT DROP
AS
SELECT lc.id AS label_code_id
FROM label_code lc
WHERE lc."ModuleName" <> 'common'
  AND lc."Description" LIKE 'template i18n %'
  AND right(
      lc."Description",
      length(': ' || lc."ModuleName" || '/' || lc."TemplateKey")
  ) = ': ' || lc."ModuleName" || '/' || lc."TemplateKey"
  AND EXISTS (
      SELECT 1
      FROM tmp_template_label common_seed
      WHERE common_seed.module_name = 'common'
        AND common_seed.template_key = 'common'
        AND common_seed.label_code = lc."LabelCode"
  )
  AND NOT EXISTS (
      SELECT 1
      FROM tmp_template_label exact_seed
      WHERE exact_seed.module_name = lc."ModuleName"
        AND exact_seed.template_key = lc."TemplateKey"
        AND exact_seed.label_code = lc."LabelCode"
  );

DELETE FROM label_code_lang lcl
USING tmp_superseded_generated_page_label superseded
WHERE lcl."LabelCode_id" = superseded.label_code_id;

DELETE FROM label_code lc
USING tmp_superseded_generated_page_label superseded
WHERE lc.id = superseded.label_code_id;

-- 2026-08-20 legacy attribute scanner 오등록 정리
-- 예전 scanner가 HTML 속성의 시작 escape(역슬래시와 큰따옴표 두 문자)까지 LabelCode로 저장한 행만 대상으로 한다.
-- 현재 정본 seed와 정확히 같은 소유자/키/코드는 제외해 정상 인용 문구와 현행 라벨을 보존한다.
CREATE TEMP TABLE tmp_legacy_malformed_template_label
ON COMMIT DROP
AS
SELECT lc.id AS label_code_id
FROM label_code lc
WHERE lc."Description" LIKE 'template i18n attribute:%'
  AND left(lc."LabelCode", 2) = chr(92) || chr(34)
  AND NOT EXISTS (
      SELECT 1
      FROM tmp_template_label seed
      WHERE seed.module_name = lc."ModuleName"
        AND seed.template_key = lc."TemplateKey"
        AND seed.label_code = lc."LabelCode"
  );

DELETE FROM label_code_lang lcl
USING tmp_legacy_malformed_template_label legacy
WHERE lcl."LabelCode_id" = legacy.label_code_id;

DELETE FROM label_code lc
USING tmp_legacy_malformed_template_label legacy
WHERE lc.id = legacy.label_code_id;

