-- 안전 공백 variant 공통화 이전 alias seed 정리
-- 생성기 지문, 한글, 유일한 현재 common canonical, 현재 exact seed 부재, 3개 외국어 번역 일치를 모두 요구한다.
CREATE TEMP TABLE tmp_superseded_whitespace_alias_label
ON COMMIT DROP
AS
SELECT lc.id AS label_code_id
FROM label_code lc
WHERE lc."Description" LIKE 'template i18n %'
  AND right(
      lc."Description",
      length(': ' || lc."ModuleName" || '/' || lc."TemplateKey")
  ) = ': ' || lc."ModuleName" || '/' || lc."TemplateKey"
  AND lc."LabelCode" ~ '[가-힣]'
  AND NOT EXISTS (
      SELECT 1
      FROM tmp_template_label exact_seed
      WHERE exact_seed.module_name = lc."ModuleName"
        AND exact_seed.template_key = lc."TemplateKey"
        AND exact_seed.label_code = lc."LabelCode"
  )
  AND 1 = (
      SELECT count(*)
      FROM tmp_template_label canonical_seed
      WHERE canonical_seed.module_name = 'common'
        AND canonical_seed.template_key = 'common'
        AND canonical_seed.description LIKE '%whitespace-variant%'
        AND replace(canonical_seed.label_code, ' ', '')
            = replace(lc."LabelCode", ' ', '')
  )
  AND EXISTS (
      SELECT 1
      FROM tmp_template_label canonical_seed
      WHERE canonical_seed.module_name = 'common'
        AND canonical_seed.template_key = 'common'
        AND canonical_seed.description LIKE '%whitespace-variant%'
        AND replace(canonical_seed.label_code, ' ', '')
            = replace(lc."LabelCode", ' ', '')
        AND 3 = (
            SELECT count(*)
            FROM tmp_template_label_lang canonical_lang
            JOIN label_code_lang alias_lang
              ON alias_lang."LabelCode_id" = lc.id
             AND alias_lang."LangCode" = canonical_lang.lang_code
             AND alias_lang."DispText" = canonical_lang.disp_text
            WHERE canonical_lang.module_name = canonical_seed.module_name
              AND canonical_lang.template_key = canonical_seed.template_key
              AND canonical_lang.label_code = canonical_seed.label_code
              AND canonical_lang.lang_code IN ('en-US', 'zh-CN', 'vi-VN')
        )
  );

DELETE FROM label_code_lang lcl
USING tmp_superseded_whitespace_alias_label superseded
WHERE lcl."LabelCode_id" = superseded.label_code_id;

DELETE FROM label_code lc
USING tmp_superseded_whitespace_alias_label superseded
WHERE lc.id = superseded.label_code_id;

INSERT INTO label_code_lang (
    "LabelCode_id", "LangCode", "DispText", "_created", "_modified"
)
SELECT lc.id, src.lang_code, src.disp_text, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM tmp_template_label_lang src
JOIN label_code lc
  ON lc."ModuleName" = src.module_name
 AND lc."TemplateKey" = src.template_key
 AND lc."LabelCode" = src.label_code
ON CONFLICT ("LabelCode_id", "LangCode")
WHERE "LabelCode_id" IS NOT NULL AND "LangCode" IS NOT NULL
DO UPDATE SET
    "DispText" = EXCLUDED."DispText",
    "_modified" = CURRENT_TIMESTAMP;
